BOOL sub_020062E0(u16 species, u8 delay, u8 form) {
    sub_02006920(POKECRY_NORMAL, species, 0, 127, HEAP_ID_FIELD2, delay, form);
    return 1;
}

void sub_02006300(int fadeOutFrames) {
    u8 *primaryAllocated = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_WAVE_OUT_PRIMARY_ALLOCATED);
    u8 *secondaryAllocated = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_WAVE_OUT_SECONDARY_ALLOCATED);
    (void)(GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_WAVE_OUT_REVERSED_PLAYBACK));

    NNS_SndPlayerStopSeq(GF_GetSoundHandle(SOUND_HANDLE_TYPE_POKEMON_CRY), fadeOutFrames);
    NNS_SndPlayerStopSeq(GF_GetSoundHandle(SOUND_HANDLE_TYPE_ECHO), fadeOutFrames);

    if (*primaryAllocated == 1) {
        sub_020058B8(WAVE_OUT_CHANNEL_PRIMARY);
        sub_02005680(WAVE_OUT_CHANNEL_PRIMARY);
    }

    if (*secondaryAllocated == 1) {
        sub_020058B8(WAVE_OUT_CHANNEL_SECONDARY);
        sub_02005680(WAVE_OUT_CHANNEL_SECONDARY);
    }

    sub_02006DB8();
    sub_02006A30();
}

BOOL IsCryFinished(void) {
    u8 *primaryAllocated = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_WAVE_OUT_PRIMARY_ALLOCATED);
    u8 *secondaryAllocated = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_WAVE_OUT_SECONDARY_ALLOCATED);
    (void)(GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_WAVE_OUT_REVERSED_PLAYBACK));
    (void)(GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_CRY_A_DELAY));

    if (*primaryAllocated == 1) {
        return sub_02005738(WAVE_OUT_CHANNEL_PRIMARY);
    }

    if (*secondaryAllocated == 1) {
        return sub_02005738(WAVE_OUT_CHANNEL_SECONDARY);
    }

    return GF_SndPlayerCountPlayingSeqByPlayerNo(0);
}
